parameters.jsCode:
const body = $input.item.json.body;
const docMap = {
  aadhaar: { name: 'Aadhaar Card', desc: 'Front and back scan/photo', required: true },
  pan: { name: 'PAN Card', desc: 'Clear scan/photo', required: true },
  bank: { name: 'Bank Account Details', desc: 'Cancelled cheque or passbook first page', required: true },
  photo: { name: 'Passport Photos', desc: '2 recent passport-size photographs', required: true },
  offer_letter: { name: 'Offer Letter Acceptance', desc: 'Signed copy of offer letter', required: true },
  relieving: { name: 'Relieving Letter', desc: 'From previous employer (if applicable)', required: false },
  education: { name: 'Education Certificates', desc: 'Highest qualification certificate', required: true },
  address_proof: { name: 'Address Proof', desc: 'Utility bill or rental agreement', required: false },
  nda: { name: 'NDA / Non-Disclosure Agreement', desc: 'Signed NDA form', required: true },
};

const requestedDocs = body.documents || Object.keys(docMap);
const docList = requestedDocs.map(d => docMap[d]).filter(Boolean);

return [{
  json: {
    employeeId: body.employeeId,
    employeeName: body.employeeName,
    email: body.email,
    position: body.position,
    documents: docList,
    deadline: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toLocaleDateString('en-IN'),
    portalUrl: process.env.PROJECTA_APP_URL + '/onboarding/' + body.employeeId
  }
}];

parameters.text:
=Write a professional, friendly document submission request email.

Employee: {{ $json.employeeName }}
Position: {{ $json.position }}
Deadline: {{ $json.deadline }}
Portal: {{ $json.portalUrl }}

Required Documents:
{{ $json.documents.filter(d => d.required).map((d, i) => `${i+1}. ${d.name} — ${d.desc}`).join('\n') }}

Optional Documents (submit if available):
{{ $json.documents.filter(d => !d.required).map(d => `• ${d.name} — ${d.desc}`).join('\n') }}

Instructions:
- Upload clear scans or photos (PDF or JPG)
- Max file size: 5MB per document
- Submit via the HR portal link above
- Contact hr@projecta.com for any questions

Format as a professional HTML email with a document checklist table.
